--
-- Initial pre-selected records from CONTACT
WITH C AS (
  SELECT
    /*xx*/ CASE
               WHEN C.event_id IS NULL THEN
                  'O'
               WHEN ( C.event_id IS NOT NULL AND (C.lic_condition_id IS NULL AND C.rqmnt_id IS NULL AND C.pss_rqmnt_id IS NULL) ) THEN
                  'E'
               WHEN ( C.event_id IS NOT NULL AND (C.lic_condition_id IS NOT NULL OR C.rqmnt_id IS NOT NULL OR C.pss_rqmnt_id IS NOT NULL) ) THEN
                  'C'
           END AS contact_level,
    /*00*/ C.offender_id,
    /*01*/ C.row_version,
    /*02*/ C.linked_contact_id,
    /*03*/ C.contact_id,
    /*04*/ C.contact_date,
    /*05*/ C.contact_start_time,
    /*06*/ C.contact_end_time,
    /*07*/ C.contact_type_id,
    /*08*/ NULL contact_type_code,
    /*09*/ NULL contact_type_desc,
    /*10*/ NULL contact_outcome_desc,
    /*11*/ C.contact_outcome_type_id,
    --
    /*12*/ NULL staff_id,
    /*13*/ NULL officer_code,
    /*14*/ NULL staff_forename,
    /*15*/ NULL staff_forename2,
    /*16*/ NULL staff_surname,
    /*17*/ NULL provider_employee_id,
    /*18*/ NULL provider_emp_code,
