    /*58*/ NULL pss_rqmnt_type_id,
    /*59*/ NULL pss_rqmnt_type_desc,
    /*60*/ NULL pss_rqmnt_sub_type_id,
    /*61*/ NULL pss_rqmnt_sub_type_desc,
