    --
    /*22*/ C.EVENT_ID,
    /*23*/ NULL event_number,
    --
    /*24*/ NULL AS disposal_type,
    --
    /*25*/ C.LIC_CONDITION_ID,
    /*26*/ C.RQMNT_ID,
    --
